import { chromium } from '@playwright/test'
import { writeFileSync } from 'node:fs'
const browser = await chromium.launch({ headless: true })
const results = []
try {
 for (const width of [1185, 485, 390]) {
  const page = await browser.newPage({ viewport: { width, height: 848 } })
  const errors = []
  page.on('pageerror', error => errors.push(error.message))
  await page.goto('http://127.0.0.1:61763/roadmap/v2')
  await page.evaluate(() => document.fonts.ready)
  for (const zoom of [1, 2]) {
   await page.evaluate(zoom => { document.documentElement.style.zoom = String(zoom) }, zoom)
   const data = await page.evaluate(() => ({
    width: innerWidth, scrollWidth: document.documentElement.scrollWidth,
    phases: [...document.querySelectorAll('.aheart-roadmap__phase')].map(phase => {
      const title = phase.querySelector('h2'), badge = phase.querySelector('.aheart-status')
      return { key: phase.querySelector('.aheart-roadmap__phase-marker').textContent.trim(),
        title: title.textContent.trim(), status: badge.textContent.trim(),
        titleBounds: title.getBoundingClientRect().toJSON(), statusBounds: badge.getBoundingClientRect().toJSON(),
        color: getComputedStyle(badge).color, background: getComputedStyle(badge).backgroundColor }
    })
   }))
   results.push({ viewport: { width, height: 848 }, cssZoom: zoom, ...data, errors })
  }
  await page.close()
 }
} finally { await browser.close() }
writeFileSync('evidence/V0/roadmap-after-pr50/layout-observations.json', JSON.stringify({
 sourceCommit: '17e72568e6197988fcea0df36c76c1c99e5a8bb2', url: 'http://127.0.0.1:61763/roadmap/v2',
 browser: 'Playwright Chromium (headless; supplements actual Chrome window inspection)',
 zoomNote: 'CSS zoom 2 is a layout probe, not a claim of native browser zoom or a physical mobile device.', results
}, null, 2) + '\n')
for (const row of results) console.log(JSON.stringify({ viewport: row.viewport, cssZoom: row.cssZoom,
 phases: row.phases.length, horizontalOverflow: row.scrollWidth > row.width, pageErrors: row.errors }))
if (results.some(row => row.scrollWidth > row.width || row.errors.length)) process.exitCode = 1
